//! 📬️ Actual Toy wire and checkpoint payloads remain in their original producer until exclusive ACK.
use super::ToolRunTickWriter;
use semio_framework_job::{StepContext,RetainedPayloadBuilder,RetainedJobPublication,JobPublicationKind,JobPayloadStream,JobOutcomeBorrow,JobOutcomeDescriptor,JobOutcomeView,JobOutcomeKind};
use semio_framework_tool_run::ToolRunTickWireCursor;
use semio_framework_value::{RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep,RetirementDemand,ValueError,ValueRefusalKind};
/// 🧵️ Owns each original wire chunk, native page, checkpoint byte source and physical close phase.
pub(super) struct OriginalToyEmission{cursor:Option<ToolRunTickWireCursor>,preview:RetainedPayloadBuilder,checkpoint:RetainedJobPublication,position:usize,state:[u8;4],prepared:bool}
impl OriginalToyEmission{
 pub(super) fn new()->Self{Self{cursor:None,preview:RetainedPayloadBuilder::new(JobPayloadStream::Preview),checkpoint:RetainedJobPublication::new(),position:0,state:[0;4],prepared:false}}
 fn metadata(cx:&mut StepContext<'_>)->Result<bool,ValueError>{let grant=cx.retained_grant();if grant.maximum_items==0||grant.maximum_depth==0{return Ok(false)}cx.consume_retained(RetainedCloneProgress{copied_items:1,..Default::default()})?;Ok(true)}
 pub(super) fn advance_preview<'a>(&'a mut self,writer:&ToolRunTickWriter,cx:&mut StepContext<'_>)->Result<Option<JobOutcomeBorrow<'a>>,ValueError>{
  if self.cursor.is_none(){if let Some((cursor,receipt))=ToolRunTickWireCursor::admit(writer,cx.retained_grant()){cx.consume_retained(receipt)?;self.cursor=Some(cursor);}return Ok(None)}
  if self.preview.published().is_none(){crate::app::tool_run::advance_original_tick_payload(writer,self.cursor.as_mut().unwrap(),&mut self.preview,&mut self.position,cx)?;return Ok(None)}
  JobOutcomeBorrow::admit_preview(cx,self.preview.published().unwrap())
 }
 pub(super) fn advance_checkpoint<'a>(&'a mut self,value:u32,cx:&mut StepContext<'_>)->Result<Option<JobOutcomeBorrow<'a>>,ValueError>{
  if !self.prepared{let grant=cx.retained_grant();if grant.maximum_items==0||grant.maximum_copy_bytes<4||grant.maximum_depth==0{return Ok(None)}self.state=value.to_le_bytes();self.prepared=true;cx.consume_retained(RetainedCloneProgress{copied_items:1,copied_bytes:4,..Default::default()})?;return Ok(None)}
  self.checkpoint.advance_from_source(JobPublicationKind::Checkpoint{applied_progress:u64::from(value)},&self.state,cx)
 }
 pub(super) fn borrow_outcome<'a>(&'a self,descriptor:&'a JobOutcomeDescriptor)->Result<JobOutcomeView<'a>,ValueError>{match descriptor.kind(){JobOutcomeKind::PreviewReady=>descriptor.preview(self.preview.published().ok_or_else(||ValueError::literal(ValueRefusalKind::InvariantViolated,"original Toy preview is not published"))?),JobOutcomeKind::CheckpointReady{..}=>self.checkpoint.borrow_outcome(descriptor),JobOutcomeKind::Complete=>descriptor.complete(None,None),JobOutcomeKind::Cancelled=>descriptor.cancelled(),JobOutcomeKind::Yield=>descriptor.yielded(),_=>Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"original Toy descriptor kind has no retained payload"))}}
 pub(super) fn preview_is_empty(&self)->bool{self.cursor.is_none()&&self.preview.terminal_is_empty()&&self.position==0}
 pub(super) fn checkpoint_is_empty(&self)->bool{self.checkpoint.terminal_is_empty()&&!self.prepared}
 pub(super) fn terminal_is_empty(&self)->bool{self.preview_is_empty()&&self.checkpoint_is_empty()}
 pub(super) fn retirement_demands(&self)->Result<RetirementDemand,ValueError>{if let Some(cursor)=self.cursor.as_ref(){return Ok(RetirementDemand{copy_bytes:if cursor.terminal_is_empty(){0}else{cursor.chunk().len()},depth:if cursor.terminal_is_empty(){1}else{8},..Default::default()})}if !self.preview.terminal_is_empty(){return self.preview.retirement_demands()}if self.position>0{return Ok(RetirementDemand{depth:1,..Default::default()})}if !self.checkpoint.terminal_is_empty(){return self.checkpoint.retirement_demands()}Ok(RetirementDemand{depth:usize::from(self.prepared),..Default::default()})}
 pub(super) fn close_step(&mut self,grant:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{let demand=self.retirement_demands()?;if self.terminal_is_empty(){return Ok(RetainedCloneStep::Complete(Default::default()))}if grant.maximum_items==0||grant.maximum_copy_bytes<demand.copy_bytes||grant.maximum_capacity_bytes<demand.capacity_bytes||grant.maximum_release_bytes<demand.release_bytes||grant.maximum_depth<demand.depth{return Ok(RetainedCloneStep::Progress(Default::default()))}if let Some(cursor)=self.cursor.as_mut(){if !cursor.terminal_is_empty(){return Ok(RetainedCloneStep::Progress(cursor.close_step(grant)))}drop(self.cursor.take());return Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,..Default::default()}))}if !self.preview.terminal_is_empty(){return self.preview.close_step_granted(grant).map(|step|RetainedCloneStep::Progress(step.progress()))}if self.position>0{self.position=0;return Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,..Default::default()}))}if !self.checkpoint.terminal_is_empty(){return self.checkpoint.close_step(grant).map(|step|RetainedCloneStep::Progress(step.progress()))}self.prepared=false;Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,..Default::default()}))}
 pub(super) fn close_in_context(&mut self,cx:&mut StepContext<'_>)->Result<bool,ValueError>{let result=self.close_step(cx.retained_grant());match result{Ok(step)=>{cx.consume_retained(step.progress())?;Ok(self.terminal_is_empty())},Err(original)=>{let _=cx.consume_retained(original.retained_progress());Err(original)}}}
}
impl Drop for OriginalToyEmission{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"original Toy wire or checkpoint abandoned before exclusive ACK and physical closure");}}
